import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BUS5y9ZA.js";const u=JSON.parse('{"title":"올바름 인력관리시스템 배포 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"deployment-guide.md","filePath":"deployment-guide.md"}'),l={name:"deployment-guide.md"};function d(i,e,n,c,s,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="올바름-인력관리시스템-배포-가이드" tabindex="-1">올바름 인력관리시스템 배포 가이드 <a class="header-anchor" href="#올바름-인력관리시스템-배포-가이드" aria-label="Permalink to &quot;올바름 인력관리시스템 배포 가이드&quot;">​</a></h1><h2 id="_1-배포-구성" tabindex="-1">1. 배포 구성 <a class="header-anchor" href="#_1-배포-구성" aria-label="Permalink to &quot;1. 배포 구성&quot;">​</a></h2><ul><li>애플리케이션: Vercel deployment server</li><li>데이터베이스·인증·저장소: Supabase</li><li>정기 작업: Supabase Cron 및 Edge Function</li><li>외부 연동: Kakao 지도, 도로명주소, Naver mail, Web Push</li></ul><h2 id="_2-사전-준비" tabindex="-1">2. 사전 준비 <a class="header-anchor" href="#_2-사전-준비" aria-label="Permalink to &quot;2. 사전 준비&quot;">​</a></h2><h3 id="_1-데이터베이스-이전-supabase" tabindex="-1">1. 데이터베이스 이전 (Supabase) <a class="header-anchor" href="#_1-데이터베이스-이전-supabase" aria-label="Permalink to &quot;1. 데이터베이스 이전 (Supabase)&quot;">​</a></h3><ol><li>(소유자) Supabase 사이트에서 신규 가입하고 이메일과 비밀번호를 생성한다.</li><li>로그인한 뒤 좌측의 <strong>Team</strong> 메뉴를 선택한다.</li><li><strong>Invite members</strong>를 선택한다.</li><li><strong>Email address</strong>에 개발자 이메일 <code>sooyongbin@gmail.com</code>을 입력한다.</li><li>개발자가 초대를 확인한다.</li><li>(소유자) <strong>Team</strong> 메뉴의 member 목록에 개발자가 나타나는지 확인한다.</li><li><strong>Manage access</strong>에서 개발자 권한을 <strong>Developer</strong>에서 <strong>OWNER</strong>로 변경한다.</li><li>(개발자) <strong>Transfer project</strong>를 진행한다. 이전 후에도 프로젝트를 조회할 수 있다.</li></ol><h3 id="_2-운영-배포-서버-vercel" tabindex="-1">2. 운영(배포) 서버 (Vercel) <a class="header-anchor" href="#_2-운영-배포-서버-vercel" aria-label="Permalink to &quot;2. 운영(배포) 서버 (Vercel)&quot;">​</a></h3><ol><li>새로운 계정 ID로 신규 가입한다.</li><li>GitHub를 연결하고 프로젝트를 생성한다. <a href="https://github.com/sooyongbin-cmd/ollbareun" target="_blank" rel="noreferrer">https://github.com/sooyongbin-cmd/ollbareun</a></li><li>**Settings → Build and Deployment → <a href="https://vercel.com/dev02-c7ef/~/settings/build-and-deployment#deployment-retention-policy" target="_blank" rel="noreferrer">Deployment Retention Policy</a>**에서 보관 정책을 1day 로 조정한다.</li><li>Supabase의 <strong>Authentication → URL Configuration → Redirect URLs</strong>에 새 Vercel 주소의 <code>/auth/callback</code>을 허용한다.</li><li>Supabase service key는 <strong>Project Settings → API Keys</strong>에서 확인한다. Vercel 서버 환경변수에만 등록하고 문서나 Git 저장소에는 기록하지 않는다.</li></ol><h3 id="_3-계정-및-설정-관리" tabindex="-1">3. 계정 및 설정 관리 <a class="header-anchor" href="#_3-계정-및-설정-관리" aria-label="Permalink to &quot;3. 계정 및 설정 관리&quot;">​</a></h3><ul><li>관리자 계정은 업무상 필요한 사용자만 등록한다.</li><li>담당자 변경 또는 퇴사 시 관리자 계정을 즉시 정리한다.</li><li>시스템 설정 코드는 운영 기능에서 참조하므로 의미를 확인한 후 수정한다.</li><li>비밀번호와 서비스 키는 문서나 메신저에 평문으로 공유하지 않는다.</li></ul><h4 id="_3-1-네이버-메일-발신-계정-등록-및-변경" tabindex="-1">3.1 네이버 메일 발신 계정 등록 및 변경 <a class="header-anchor" href="#_3-1-네이버-메일-발신-계정-등록-및-변경" aria-label="Permalink to &quot;3.1 네이버 메일 발신 계정 등록 및 변경&quot;">​</a></h4><p>특이사항 보고에 사용할 네이버 발신 계정을 새로 등록하거나 교체할 때 다음 순서로 진행한다. 현재 구현에서는 코드 수정 없이 네이버 계정 설정과 Vercel 환경변수 변경으로 적용할 수 있다.</p><h5 id="_1-네이버-2단계-인증과-애플리케이션-비밀번호-준비" tabindex="-1">1. 네이버 2단계 인증과 애플리케이션 비밀번호 준비 <a class="header-anchor" href="#_1-네이버-2단계-인증과-애플리케이션-비밀번호-준비" aria-label="Permalink to &quot;1. 네이버 2단계 인증과 애플리케이션 비밀번호 준비&quot;">​</a></h5><ol><li>발신용 네이버 계정으로 로그인한다.</li><li>네이버 계정의 보안설정에서 2단계 인증을 활성화한다.</li><li>애플리케이션 비밀번호를 발급한다. SMTP 인증에는 일반 로그인 비밀번호가 아닌 이 비밀번호를 사용한다.</li></ol><p>네이버는 2025년 6월 24일부터 외부 메일 연동에 2단계 인증과 애플리케이션 비밀번호를 요구한다. 자세한 절차는 <a href="https://help.naver.com/service/30029/contents/24347?lang=ko&amp;osType=COMMONOS" target="_blank" rel="noreferrer">네이버 공식 FAQ</a>를 참고한다.</p><h5 id="_2-네이버-메일에서-smtp-사용-허용" tabindex="-1">2. 네이버 메일에서 SMTP 사용 허용 <a class="header-anchor" href="#_2-네이버-메일에서-smtp-사용-허용" aria-label="Permalink to &quot;2. 네이버 메일에서 SMTP 사용 허용&quot;">​</a></h5><ol><li>PC 네이버 메일의 <strong>환경설정 → POP3/IMAP 설정 → POP3/SMTP 설정</strong>으로 이동한다.</li><li><strong>POP3/SMTP 사용</strong>을 <strong>사용함</strong>으로 변경하고 저장한다.</li><li>SMTP 서버는 <code>smtp.naver.com</code>, 포트는 <code>465</code>, 보안 연결은 SSL을 사용한다.</li></ol><p><a href="https://help.naver.com/service/30029/contents/21341?lang=ko&amp;osType=PC" target="_blank" rel="noreferrer">네이버 SMTP 설정 안내</a></p><h5 id="_3-vercel-환경변수-등록" tabindex="-1">3. Vercel 환경변수 등록 <a class="header-anchor" href="#_3-vercel-환경변수-등록" aria-label="Permalink to &quot;3. Vercel 환경변수 등록&quot;">​</a></h5><p>Vercel의 해당 프로젝트에서 <strong>Settings → Environment Variables</strong>로 이동하여 아래 값을 등록하거나 변경한다. 운영 사이트에는 <strong>Production</strong> 환경으로 적용한다.</p><table tabindex="0"><thead><tr><th>환경변수</th><th>입력할 값</th><th>비고</th></tr></thead><tbody><tr><td><code>NAVER_SMTP_USER</code></td><td>새 발신 계정 이메일, 예: <code>example@naver.com</code></td><td>필수</td></tr><tr><td><code>NAVER_SMTP_PASSWORD</code></td><td>네이버에서 발급한 애플리케이션 비밀번호</td><td>일반 로그인 비밀번호 사용 불가</td></tr><tr><td><code>NAVER_SMTP_PORT</code></td><td><code>465</code></td><td>필수. 현재 코드는 이 포트에서 SSL 사용</td></tr><tr><td><code>NAVER_SMTP_FROM</code></td><td>새 발신 계정 이메일</td><td>생략하면 <code>NAVER_SMTP_USER</code> 사용. 계정 교체 시 기존 주소가 남지 않도록 확인</td></tr></tbody></table><p>애플리케이션 비밀번호는 환경변수로만 저장하며 GitHub 코드, 프로젝트 문서, 메신저에 기록하지 않는다. SMTP 서버 주소는 코드에서 <code>smtp.naver.com</code>으로 지정되어 있으므로 별도 환경변수를 추가할 필요가 없다.</p><h5 id="_4-보고서-수신-주소-설정" tabindex="-1">4. 보고서 수신 주소 설정 <a class="header-anchor" href="#_4-보고서-수신-주소-설정" aria-label="Permalink to &quot;4. 보고서 수신 주소 설정&quot;">​</a></h5><ol><li><a href="https://ollbareun.vercel.app/manager/system/configs" target="_blank" rel="noreferrer">관리자 시스템설정</a>으로 이동한다.</li><li>시스템코드 **<code>manager_email</code>**의 내용을 보고서를 받을 이메일 주소로 설정한다.</li></ol><p>발신 계정은 Vercel 환경변수에서, 수신 주소는 시스템설정의 <code>manager_email</code>에서 관리한다. 수신 주소만 변경한다면 네이버 발신 계정을 새로 등록하거나 SMTP 환경변수를 변경할 필요가 없다.</p><h5 id="_5-재배포-및-수신-확인" tabindex="-1">5. 재배포 및 수신 확인 <a class="header-anchor" href="#_5-재배포-및-수신-확인" aria-label="Permalink to &quot;5. 재배포 및 수신 확인&quot;">​</a></h5><ol><li>환경변수 저장 후 Vercel에서 <strong>Redeploy</strong>를 실행한다. 환경변수 변경은 새 배포부터 적용된다. <a href="https://vercel.com/docs/environment-variables" target="_blank" rel="noreferrer">Vercel 환경변수 안내</a></li><li>배포 완료 후 근무자의 <strong>특이사항</strong> 화면에서 테스트 보고를 작성한다. 관리자에게 테스트임을 알 수 있도록 내용에 <strong>메일 설정 테스트</strong>를 명시한다.</li><li><strong>보고하기</strong>를 누르고 완료 안내에서 NAVER 이메일 발송 결과를 확인한다.</li><li><code>manager_email</code>에 설정한 수신 계정의 받은편지함과 스팸함에서 실제 수신 여부를 확인한다.</li></ol><p>현재 <strong>보고하기</strong>는 보고서를 한 번 저장한 뒤 관리자 푸시알림 전송을 시도하고, 이어서 NAVER 이메일을 전송한다. 따라서 테스트 보고도 관리자 푸시알림이 함께 발송된다. 푸시 전송 실패 시에도 이메일 발송은 시도하며, 완료 안내에서 두 결과를 각각 확인할 수 있다.</p><h5 id="발송-실패-시-확인-사항" tabindex="-1">발송 실패 시 확인 사항 <a class="header-anchor" href="#발송-실패-시-확인-사항" aria-label="Permalink to &quot;발송 실패 시 확인 사항&quot;">​</a></h5><ul><li>네이버 계정의 2단계 인증 및 POP3/SMTP 사용 설정을 확인한다.</li><li><code>NAVER_SMTP_PASSWORD</code>에 유효한 애플리케이션 비밀번호가 입력되어 있는지 확인한다.</li><li><code>NAVER_SMTP_USER</code>와 <code>NAVER_SMTP_FROM</code>이 새 발신 계정으로 설정되어 있는지 확인한다.</li><li><code>NAVER_SMTP_PORT</code>가 <code>465</code>인지, 환경변수가 Production에 적용되어 있는지 확인한다.</li><li>환경변수 변경 후 재배포했는지 확인한다.</li><li><code>manager_email</code>의 수신 주소, 스팸함 및 Vercel 오류 로그를 확인한다.</li></ul><h4 id="_3-2-공휴일-정보-api-신청-및-설정" tabindex="-1">3.2 공휴일 정보 API 신청 및 설정 <a class="header-anchor" href="#_3-2-공휴일-정보-api-신청-및-설정" aria-label="Permalink to &quot;3.2 공휴일 정보 API 신청 및 설정&quot;">​</a></h4><ol><li><a href="https://www.data.go.kr/data/15012690/openapi.do" target="_blank" rel="noreferrer">공공데이터포털 한국천문연구원 특일 정보</a>에 접속하고 로그인합니다.</li><li><strong>활용신청</strong>을 선택하여 사용 목적과 필요한 신청 항목을 입력합니다. 신청한 서비스의 승인 상태와 이용 가능한 호출 한도를 확인합니다.</li><li>마이페이지의 OpenAPI 활용 내역에서 해당 서비스의 **일반 인증키(Decoding)**를 확인합니다. 인증키는 공개 문서나 GitHub에 올리지 않습니다.</li><li>Vercel 프로젝트의 Settings → Environment Variables에 서버 환경변수 <strong>DATA_GO_KR_SERVICE_KEY</strong>를 만들고 인증키를 값으로 등록합니다. 운영 서비스는 Production 환경에 적용합니다. 변수 이름에 NEXT_PUBLIC_을 붙이지 않습니다.</li><li>환경변수를 저장한 뒤 재배포(Redeploy)합니다. 로컬 개발 시에는 같은 변수를 커밋하지 않는 .env.local에 설정합니다.</li><li>관리자 → 직원관리 → <strong>공휴일관리</strong>에서 연도를 입력하고 <strong>공휴일가져오기</strong>를 누릅니다. 확인창에서 해당 연도를 확인하고 승인합니다.</li></ol><p>공휴일 조회 기능(getRestDeInfo)으로 해당 연도의 자료를 받아 공휴일 여부가 Y인 날짜만 저장합니다. 신규 날짜의 선택값은 Y이며, 이미 존재하는 날짜는 수정하지 않고 건너뜁니다. 다시 가져와도 기존 이름과 선택값은 유지됩니다. 결과 메시지에서 등록 건수와 건너뛴 건수를 확인합니다.</p><p>목록의 <strong>선택</strong> 체크박스를 변경하면 Y/N 값이 즉시 저장됩니다. <strong>휴일추가</strong>에서는 날짜를 입력하여 선택값 Y로 직접 등록할 수 있습니다. 중복 날짜는 등록되지 않습니다. 공휴일 선택값은 야간근무(2)의 배정 저장 시 일정 생성에 자동 반영됩니다. 선택값이 <code>Y</code>인 공휴일은 주말과 같은 휴무일 기준으로 처리됩니다. 일반근무(0)와 격일근무(1)은 공휴일·주말을 자동 휴무로 처리하지 않으므로 필요한 경우 <strong>근무지배정 상세</strong> 화면에서 휴무일을 수동 지정합니다.</p><p>인증키가 없으면 설정 안내가 표시됩니다. 가져오기 실패 시 활용승인 여부, 인증키, 요청 한도, 공공데이터포털 서비스 상태를 확인합니다. 임시공휴일 등 변경 사항이 발표되면 해당 연도를 다시 가져오고, 기존 자료의 변경이 필요한 경우에는 선택값을 직접 조정합니다. API 등록 정보와 제공 범위는 공공데이터포털의 최신 안내를 기준으로 확인합니다.</p><h4 id="_3-3-교육-알림-cron-작업-등록-위치" tabindex="-1">3.3 교육 알림 Cron 작업 등록 위치 <a class="header-anchor" href="#_3-3-교육-알림-cron-작업-등록-위치" aria-label="Permalink to &quot;3.3 교육 알림 Cron 작업 등록 위치&quot;">​</a></h4><p>교육 알림 자동 발송을 위한 Supabase Cron 작업은 다음 메뉴에서 등록·수정하고 활성화 상태를 확인한다.</p><ul><li>메뉴 : Integrations - Cron</li></ul><h2 id="_3-환경변수" tabindex="-1">3. 환경변수 <a class="header-anchor" href="#_3-환경변수" aria-label="Permalink to &quot;3. 환경변수&quot;">​</a></h2><table tabindex="0"><thead><tr><th>변수</th><th>용도</th><th>노출 범위</th></tr></thead><tbody><tr><td><code>NEXT_PUBLIC_SUPABASE_URL</code></td><td>Supabase 프로젝트 URL</td><td>클라이언트 허용</td></tr><tr><td><code>NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY</code></td><td>Supabase 공개키</td><td>클라이언트 허용</td></tr><tr><td><code>SUPABASE_SECRET_KEY</code> 또는 <code>SUPABASE_SERVICE_ROLE_KEY</code></td><td>서버 관리 작업</td><td>서버 전용</td></tr><tr><td><code>kakao_map_key</code></td><td>Kakao 지도·좌표 변환</td><td>서버 전용</td></tr><tr><td><code>juso_key</code></td><td>도로명주소 검색</td><td>서버 전용</td></tr><tr><td><code>NAVER_SMTP_USER</code></td><td>Naver SMTP 계정</td><td>서버 전용</td></tr><tr><td><code>NAVER_SMTP_PASSWORD</code></td><td>Naver SMTP 비밀번호</td><td>서버 전용</td></tr><tr><td><code>NAVER_SMTP_PORT</code></td><td>SMTP 포트</td><td>서버 전용</td></tr><tr><td><code>NAVER_SMTP_FROM</code></td><td>발신 주소</td><td>서버 전용</td></tr><tr><td><code>NEXT_PUBLIC_VAPID_PUBLIC_KEY</code></td><td>Web Push 공개키</td><td>클라이언트 허용</td></tr><tr><td><code>VAPID_PRIVATE_KEY</code></td><td>Web Push 개인키</td><td>서버 전용</td></tr><tr><td><code>EDUCATION_REMINDER_CRON_SECRET</code></td><td>교육 알림 예약 호출 검증</td><td>서버 전용</td></tr></tbody></table><h2 id="_4-배포-절차" tabindex="-1">4. 배포 절차 <a class="header-anchor" href="#_4-배포-절차" aria-label="Permalink to &quot;4. 배포 절차&quot;">​</a></h2><ol><li>대상 커밋과 변경 내역을 확인한다.</li><li><code>npm ci</code>, <code>npm run lint</code>, <code>npm test</code>, <code>npm run build</code>를 통과시킨다.</li><li>Supabase 마이그레이션을 스테이징에서 먼저 적용한다.</li><li>운영 DB를 백업하고 마이그레이션을 적용한다.</li><li>Vercel 환경변수를 설정하고 대상 커밋을 배포한다.</li><li>필요한 Supabase Edge Function과 Vault 비밀값을 배포한다.</li><li>도메인, 인증 콜백 URL, PWA 파일과 Service Worker를 확인한다.</li><li>배포 후 점검을 완료하고 배포 기록을 남긴다.</li></ol><h2 id="_5-배포-후-점검" tabindex="-1">5. 배포 후 점검 <a class="header-anchor" href="#_5-배포-후-점검" aria-label="Permalink to &quot;5. 배포 후 점검&quot;">​</a></h2><ul><li>회사소개 홈페이지와 관리자·근무자 진입 화면 응답</li><li>관리자 로그인과 보호 화면 접근</li><li>직원·근무지·배정 조회</li><li>테스트 근무자의 로그인과 프로필 조회</li><li>지도·주소 검색, Naver mail, 푸시 알림 연결</li><li>정적 이미지, 아이콘, 폰트, PWA 설치 정보</li><li>서버 로그의 반복 오류와 5xx 응답 여부</li></ul>',44)])])}const P=t(l,[["render",d]]);export{u as __pageData,P as default};
